from fractions import Fraction
from math import inf

def p_adic_valuation(x: Fraction, p: int = 3) -> float:
    """p-adic order of a rational; v(0)=+inf, v(ab)=v(a)+v(b)."""
    if x == 0:
        return inf
    num, den, order = x.numerator, x.denominator, 0
    while num % p == 0:
        num //= p; order += 1
    while den % p == 0:
        den //= p; order -= 1
    return float(order)

def winner_takes_all(terms: list[Fraction], p: int = 3) -> None:
    vals = [p_adic_valuation(t, p) for t in terms]
    total = sum(terms, Fraction(0))
    # exactly one strict minimiser => v(sum) = that minimum
    assert vals.count(min(vals)) == 1
    assert p_adic_valuation(total, p) == min(vals)
    print(f"v(sum)={p_adic_valuation(total,p)} = min v={min(vals)}")

winner_takes_all([Fraction(1), Fraction(9), Fraction(81)])

from fractions import Fraction
from math import inf

def p_adic_valuation(x: Fraction, p: int = 3) -> float:
    if x == 0:
        return inf
    num, den, order = x.numerator, x.denominator, 0
    while num % p == 0:
        num //= p; order += 1
    while den % p == 0:
        den //= p; order -= 1
    return float(order)

def attained_at_least_twice(weights: list[float]) -> bool:
    if len(weights) < 2:
        return False
    m = min(weights)
    return sum(1 for w in weights if w == m) >= 2

# A point (x,y) on the line a*X + b*Y + c = 0 tropicalizes onto the corner locus.
a, b, x, y = Fraction(3), Fraction(1, 9), Fraction(2), Fraction(27)
c = -(a * x + b * y)
monomials = [a * x, b * y, c]
weights = [p_adic_valuation(m) for m in monomials]
assert attained_at_least_twice(weights)
print("corner locus weights:", weights)

from itertools import product

def trop_eval(poly, x):
    """min-plus eval: min_i (a_i + <m_i, x>)."""
    return min(a + sum(mc*xc for mc, xc in zip(m, x)) for a, m in poly)

def trop_mul(P, Q):
    """tropical product: coeffs add, exponents add."""
    return [(ap+aq, [mp+mq for mp, mq in zip(mp_, mq_)])
            for ap, mp_ in P for aq, mq_ in Q]

P = [(0.0, [0.0]), (1.0, [1.0])]   # min(0, 1+x)
Q = [(2.0, [0.0]), (0.0, [2.0])]   # min(2, 2x)
PQ = trop_mul(P, Q)
for xv in [-2.0, 0.0, 3.0]:
    assert abs(trop_eval(PQ,[xv]) - (trop_eval(P,[xv])+trop_eval(Q,[xv]))) < 1e-9
print("eval(P*Q) = eval(P)+eval(Q): tropical degrees add (Bezout)")

